SELECT tick_id, stock_code, traded_at, price, volume, change_rate, acc_volume
FROM quote_tick
WHERE stock_code = #{stockCode}
  AND trade_date = #{tradeDate}
  AND traded_at >= #{from}
  AND tick_id > #{afterId}
ORDER BY tick_id
LIMIT #{limit}
